import{_ as c,r as t,o as l,c as i,e as p,a as n,d as a,s as u}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"扩展方法论 - October CMS - 3.x","titleTemplate":false,"description":"了解扩展 October CMS 的常用方法。","frontmatter":{"subtitle":"了解扩展 October CMS 的常用方法。"},"headers":[{"level":2,"title":"通过插件注册进行扩展","slug":"通过插件注册进行扩展","link":"#通过插件注册进行扩展","children":[]},{"level":2,"title":"通过事件进行扩展","slug":"通过事件进行扩展","link":"#通过事件进行扩展","children":[{"level":3,"title":"订阅事件","slug":"订阅事件","link":"#订阅事件","children":[]},{"level":3,"title":"声明 / 触发事件","slug":"声明-触发事件","link":"#声明-触发事件","children":[]}]},{"level":2,"title":"扩展后端视图","slug":"扩展后端视图","link":"#扩展后端视图","children":[]},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例","children":[{"level":3,"title":"扩展用户模型","slug":"扩展用户模型","link":"#扩展用户模型","children":[]},{"level":3,"title":"扩展后端表单","slug":"扩展后端表单","link":"#扩展后端表单","children":[]},{"level":3,"title":"扩展后端列表","slug":"扩展后端列表","link":"#扩展后端列表","children":[]},{"level":3,"title":"扩展组件","slug":"扩展组件","link":"#扩展组件","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/extend/extending.md","filePath":"3.x/zh-cn/extend/extending.md"}'),r={name:"3.x/zh-cn/extend/extending.md"};function k(d,s,g,m,h,v){const e=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[p(e),s[0]||(s[0]=n("h1",null,"扩展方法论",-1)),p(o),s[1]||(s[1]=n("h2",{id:"通过插件注册进行扩展"},[n("a",{href:"#通过插件注册进行扩展",class:"header-anchor"},"#"),a(" 通过插件注册进行扩展")],-1)),s[2]||(s[2]=n("p",null,[a("在几乎所有情况下，扩展 October CMS 都是在插件注册文件中完成的，它本质上是一个 "),n("a",{href:"https://laravel.com/docs/10.x/providers",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel 服务提供者"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a("。注册文件名为 "),n("strong",null,"Plugin.php"),a("，位于插件的根目录中。")],-1)),s[3]||(s[3]=u(`<p>以下是可在插件注册类中重写的扩展方法：</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><strong>register()</strong></td><td>插件首次注册时调用，在 <code>boot</code> 之前调用。</td></tr><tr><td><strong>boot()</strong></td><td>在请求路由之前调用，在 <code>register</code> 之后调用。</td></tr><tr><td><strong>registerMarkupTags()</strong></td><td>注册可在 CMS 中使用的<a href="./twig-tags.html">额外标记标签</a>。</td></tr><tr><td><strong>registerComponents()</strong></td><td>注册此插件使用的任何 <a href="./cms-components.html">CMS 组件</a>。</td></tr><tr><td><strong>registerNavigation()</strong></td><td>注册此插件的<a href="./backend/navigation.html">后端导航菜单项</a>。</td></tr><tr><td><strong>registerPermissions()</strong></td><td>注册此插件使用的任何<a href="./backend/permissions.html">后端权限</a>。</td></tr><tr><td><strong>registerSettings()</strong></td><td>注册此插件使用的任何<a href="./settings/settings.html">后端配置链接</a>。</td></tr><tr><td><strong>registerFormWidgets()</strong></td><td>注册此插件提供的任何<a href="./forms/form-widgets.html">后端表单部件</a>。</td></tr><tr><td><strong>registerReportWidgets()</strong></td><td>注册任何<a href="./backend/report-widgets.html">后端报表部件</a>，包括仪表盘部件。</td></tr><tr><td><strong>registerListColumnTypes()</strong></td><td>注册此插件提供的任何<a href="./lists/list-controller.html">自定义列表列类型</a>。</td></tr><tr><td><strong>registerMailTemplates()</strong></td><td>注册此插件提供的任何<a href="./system/sending-mail.html">邮件视图模板</a>。</td></tr><tr><td><strong>registerMailLayouts()</strong></td><td>注册此插件提供的任何<a href="./system/sending-mail.html">邮件视图布局</a>。</td></tr><tr><td><strong>registerMailPartials()</strong></td><td>注册此插件提供的任何<a href="./system/sending-mail.html">邮件视图片段</a>。</td></tr><tr><td><strong>registerSchedule()</strong></td><td>注册定期执行的<a href="./system/scheduling.html">计划任务</a>。</td></tr><tr><td><strong>registerContentFields()</strong></td><td>注册 Tailor 蓝图使用的<a href="./../extend/tailor-fields.html">内容字段</a>。</td></tr></tbody></table></div><h2 id="通过事件进行扩展"><a href="#通过事件进行扩展" class="header-anchor">#</a> 通过事件进行扩展</h2><p><a href="./services/event.html">事件服务</a>是注入或修改核心类或其他插件功能的主要方式。可以在任何类中通过在 PHP 文件顶部（命名空间声明之后）添加 <code>use Event</code> 来导入 Event facade 以使用此服务。</p><h3 id="订阅事件"><a href="#订阅事件" class="header-anchor">#</a> 订阅事件</h3><p>订阅事件最常见的位置是插件注册文件的 <code>boot</code> 方法。例如，当用户首次注册时，您可能希望将其添加到第三方邮件列表中，这可以通过订阅 <code>rainlab.user.register</code> 全局事件来实现。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.user.register&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token comment">// Code to register $user-&gt;email to mailing list</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>同样的效果也可以通过扩展模型的构造函数并使用本地事件来实现。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.register&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Code to register $model-&gt;email to mailing list</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="声明-触发事件"><a href="#声明-触发事件" class="header-anchor">#</a> 声明 / 触发事件</h3><p>通过在实现了 <code>October\\Rain\\Support\\Traits\\Emitter</code> 的对象实例上调用 <code>fireEvent()</code> 来触发本地事件。由于本地事件仅在特定对象实例上触发，因此不需要对其进行命名空间划分，因为在本地上下文中，给定项目不太可能在相同对象上触发多个同名事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>全局事件通过调用 <code>Event::fire()</code> 来触发。由于这些事件在整个应用程序中是全局的，最佳实践是在事件名称中包含供应商信息来进行命名空间划分。如果您的插件作者是 ACME，插件名称是 Blog，那么 ACME.Blog 插件提供的所有全局事件都应以 <code>acme.blog</code> 为前缀。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果在同一位置同时提供全局和本地事件，最佳实践是在全局事件之前触发本地事件，以便本地事件具有优先权。此外，全局事件应将触发本地事件的对象实例作为第一个参数提供。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.blog.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token variable">$firstParam</span><span class="token punctuation">,</span> <span class="token variable">$secondParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>一旦订阅了此事件，参数就可以在处理方法中使用。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Global</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$param1</span><span class="token punctuation">,</span> <span class="token variable">$param2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;posted. Parameters: &#39;</span> <span class="token operator">.</span> <span class="token variable">$param1</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; &#39;</span> <span class="token operator">.</span> <span class="token variable">$param2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Local</span>
<span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post.beforePost&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$param1</span><span class="token punctuation">,</span> <span class="token variable">$param2</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;posted. Parameters: &#39;</span> <span class="token operator">.</span> <span class="token variable">$param1</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39; &#39;</span> <span class="token operator">.</span> <span class="token variable">$param2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="扩展后端视图"><a href="#扩展后端视图" class="header-anchor">#</a> 扩展后端视图</h2><p>有时您可能希望允许后端视图文件或片段可被扩展，例如工具栏。这可以通过所有后端控制器中的 <code>fireViewEvent</code> 方法来实现。</p><p>将以下代码放入您的视图文件中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>footer-area-extension<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireViewEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.auth.extendSigninView&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$firstParam</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>这将允许其他插件通过挂钩事件并返回所需的标记来向此区域注入 HTML。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.auth.extendSigninView&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">,</span> <span class="token variable">$firstParam</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;&lt;a href=&quot;#&quot;&gt;Sign in with Google!&lt;/a&gt;&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>事件处理程序中的第一个参数始终是调用对象（控制器）。</p></div><p>上面的示例将输出以下标记：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>footer-area-extension<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>#<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Sign in with Google!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="使用示例"><a href="#使用示例" class="header-anchor">#</a> 使用示例</h2><p>以下是一些关于如何使用事件的实际示例。</p><h3 id="扩展用户模型"><a href="#扩展用户模型" class="header-anchor">#</a> 扩展用户模型</h3><p>此示例将通过绑定其本地事件来修改 <code>User</code> 模型的 <code>model.getAttribute</code> 事件。这是在插件注册文件的 <code>boot</code> 方法中执行的。在两种情况下，当访问 <code>$model-&gt;foo</code> 属性时，它将返回值 <strong>bar</strong>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Local event hook that affects all users</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.getAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Double event hook that affects user #2 only</span>
<span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.afterFetch&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">id</span> <span class="token operator">!==</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>

        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.getAttribute&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$attribute</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要为引入的字段添加模型验证，请挂钩 <code>beforeValidate</code> 事件并抛出 <code>ValidationException</code> 异常。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeValidate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">billing_first_name</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;billing_first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;First name is required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="扩展后端表单"><a href="#扩展后端表单" class="header-anchor">#</a> 扩展后端表单</h3><div class="custom-block aside"><p>有多种方式可以扩展后端表单，请参阅<a href="./forms/form-controller.html">后端控制器文章</a>了解更多信息。</p></div><p>此示例将监听 <code>Backend\\Widget\\Form</code> 部件的 <code>backend.form.extendFields</code> 全局事件，并在 Form 部件用于修改用户时注入一些额外字段。此事件也在插件注册文件的 <code>boot</code> 方法中订阅。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Extend all backend form usage</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.form.extendFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Only apply this listener when the Users controller is being used</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Only apply this listener when the User model is being modified</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">model</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Only apply this listener when the Form widget in question is a root-level</span>
    <span class="token comment">// Form widget (not a repeater, nestedform, etc)</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">isNested</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add an extra birthday field</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;birthday&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Birthday&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Select the users birthday&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;datepicker&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Remove a Surname field</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeField</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;surname&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>您也可以使用 <code>backend.form.extendFieldsBefore</code> 事件来添加字段。</p></div><h3 id="扩展后端列表"><a href="#扩展后端列表" class="header-anchor">#</a> 扩展后端列表</h3><p>此示例将修改 <code>Backend\\Widget\\Lists</code> 类的 <code>backend.list.extendColumns</code> 全局事件，并在列表用于修改用户的条件下注入一些额外的列值。此事件也在插件注册文件的 <code>boot</code> 方法中订阅。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Extend all backend list usage</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Only for the User controller</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Users</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Only for the User model</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">model</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>RainLab<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Add an extra birthday column</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">addColumns</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;birthday&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Birthday&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Remove a Surname column</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;surname&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="扩展组件"><a href="#扩展组件" class="header-anchor">#</a> 扩展组件</h3><p>此示例将在 <code>Topic</code> 组件中声明一个新的全局事件 <code>rainlab.forum.topic.post</code> 和本地事件 <code>topic.post</code>。这是在<a href="./cms-components.html">组件类定义</a>中完成的。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Topic</span> <span class="token keyword">extends</span> <span class="token class-name">ComponentBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onPost</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>

        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;topic.post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$postUrl</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.forum.topic.post&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$postUrl</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>接下来将演示如何在<a href="./../cms/themes/layouts.html">布局执行生命周期</a>中挂钩此新事件。当 <code>Topic</code> 组件（上方）中的 <code>onPost</code> 事件处理程序被调用时，这将写入跟踪日志。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">topic</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">slug</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :slug }}</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">topic</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;topic.post&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">,</span> <span class="token variable">$postUrl</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token function">trace_log</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;A post has been submitted at &#39;</span><span class="token operator">.</span><span class="token variable">$postUrl</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./services/event.html">Event 服务</a></li></ul></div>`,49))])}const y=c(r,[["render",k]]);export{b as __pageData,y as default};
